// Helper function to write result and exit
int write_result_and_exit(const PlanGenerationResult& result, const char* output_file) {
    std::fstream output(output_file, std::ios::out | std::ios::trunc | std::ios::binary);
    if (!output || !result.SerializeToOstream(&output)) {
        std::cerr << "Error: Could not write result to file: " << output_file << std::endl;
        return 1;
    }
    if (planmt::Config::instance().is_info()) {
        std::cout << "C++ Planner: Successfully wrote result to: " << output_file << std::endl;
    }
    google::protobuf::ShutdownProtobufLibrary();
    return 0;
}

// Function to export formula and exit
int export_formula_and_exit(const planmt::Problem& problem) {
    auto& config = planmt::Config::instance();

    // Validate formula export parameters
    if (config.formula_export.timestep < 0) {
        std::cerr << "Error: --formula-timestep must be specified with --export-formula" << std::endl;
        return 1;
    }

    if (config.formula_export.output_file.empty()) {
        std::cerr << "Error: --formula-output must be specified with --export-formula" << std::endl;
        return 1;
    }

    // Only allow formula export with strategies that support it
    auto strategy = planmt::StrategyRegistry::create(config.planner.strategy);
    if (!strategy->supports_formula_export()) {
        std::cerr << "Error: Formula export is not supported by strategy '"
                  << strategy->get_name() << "'" << std::endl;
        return 1;
    }

    try {
        // Create Z3 context
        z3::context ctx;

        // Create encoder, parallelism, and interference analyzer using strategy
        auto encoder = strategy->create_encoder(problem, ctx);
        auto parallelism = strategy->create_parallelism();
        auto interference = strategy->create_interference(problem);

        // Inject interference analyzer into parallelism strategy
        parallelism->set_interference_analyzer(std::move(interference));

        // Set parallelism strategy on encoder
        encoder->set_parallelism_strategy(std::move(parallelism));

        if (config.is_info()) {
            std::cout << "Exporting formula for timestep " << config.formula_export.timestep
                      << " using strategy: " << encoder->get_parallelism_strategy_name() << std::endl;
        }

        // Create formula exporter and generate formula
        planmt::FormulaExporter exporter(problem, *encoder, ctx);
        std::string formula = exporter.export_formula(config.formula_export.timestep);

        // Output formula to file
        std::ofstream output_file(config.formula_export.output_file);
        if (!output_file) {
            std::cerr << "Error: Could not open output file: " << config.formula_export.output_file << std::endl;
            return 1;
        }
        output_file << formula;
        if (config.is_info()) {
            std::cout << "Formula exported to: " << config.formula_export.output_file << std::endl;
        }

        google::protobuf::ShutdownProtobufLibrary();
        return 0;

    } catch (const std::exception& e) {
        std::cerr << "Error during formula export: " << e.what() << std::endl;
        google::protobuf::ShutdownProtobufLibrary();
        return 1;
    }
}

// Function to print the complete planning problem structure using enhanced planning classes
PlanGenerationResult solve_planning_problem(const planmt::Problem& problem) {
    auto& config = planmt::Config::instance();
    
    // Memory tracking is always enabled
    
    PlanGenerationResult result;
    auto* log_message = result.add_log_messages();
    log_message->set_level(LogMessage_LogLevel_INFO);

        // Create Z3 context
    z3::context ctx;

    // Create strategy
    auto strategy = planmt::StrategyRegistry::create(config.planner.strategy);

    if (config.is_info()) {
        std::cout << "Using strategy: " << strategy->get_name() << std::endl;
    }

    // Create encoder, parallelism, and interference analyzer using strategy
    auto encoder = strategy->create_encoder(problem, ctx);
    auto parallelism = strategy->create_parallelism();
    auto interference = strategy->create_interference(problem);

    // Inject interference analyzer into parallelism strategy
    parallelism->set_interference_analyzer(std::move(interference));

    // Set parallelism strategy on encoder
    encoder->set_parallelism_strategy(std::move(parallelism));

    // Create planner (start with default constructor, then set propagator)
    planmt::SequentialPlanner planner(problem, *encoder, ctx);

    // Get solver reference and create propagator using strategy
    auto propagator = strategy->create_propagator(planner.get_solver(), problem, *encoder);
    planner.set_propagator_strategy(std::move(propagator));

    // Call planner.search() and get the result
    planmt::Plan plan = planner.search();
    if (planner.solution_found()) {
        // Plan found (even if empty) - populate the result
        result.set_status(PlanGenerationResult_Status_SOLVED_SATISFICING);
        
        // Convert plan to protobuf and set it in the result
        *result.mutable_plan() = plan.to_protobuf();
        
        if (config.is_info()) {
            log_message = result.add_log_messages();
            log_message->set_level(LogMessage_LogLevel_INFO);
            log_message->set_message("Plan found with " + std::to_string(plan.length()) + " actions.");
        }
    } else {
        // No plan found
        result.set_status(PlanGenerationResult_Status_UNSOLVABLE_INCOMPLETELY);
        if (config.is_info()) {
            log_message = result.add_log_messages();
            log_message->set_level(LogMessage_LogLevel_INFO);
            log_message->set_message("No plan found within the search limit.");
        }
    }
    
    if (config.is_verbose()) {
        log_message = result.add_log_messages();
        log_message->set_level(LogMessage_LogLevel_INFO);
        log_message->set_message("Finished solving the problem.");
    }
    
    // Add memory tracking information to result
    double current_memory = planmt::MemoryTracker::instance().get_current_memory_mb();
    
    log_message = result.add_log_messages();
    log_message->set_level(LogMessage_LogLevel_INFO);
    log_message->set_message("Memory usage - Current: " + std::to_string(current_memory) + " MB");

    return result;
}
int main(int argc, char* argv[]) {
    GOOGLE_PROTOBUF_VERIFY_VERSION;
    
    try {
        // Initialize configuration first
        planmt::Config::instance().initialize(argc, argv);
        auto& config = planmt::Config::instance();
        
        if (argc < 3) {
            std::cerr << "Usage: " << argv[0] << " <input_problem.pb> <output_solution.pb> [OPTIONS]" << std::endl;
            std::cerr << "Use --help for detailed options" << std::endl;
            return 1;
        }
    } catch (const std::exception& e) {
        std::cerr << "Configuration error: " << e.what() << std::endl;
        return 1;
    }

    // Read the problem from the input file
    Problem problem_msg;
    std::fstream input(argv[1], std::ios::in | std::ios::binary);
    if (!input || !problem_msg.ParseFromIstream(&input)) {
        std::cerr << "Error: Could not open or parse problem file: " << argv[1] << std::endl;
        return 1;
    }

    // Create a Problem wrapper from the protobuf message
    planmt::Problem planning_problem(problem_msg);
    //std::cout << planning_problem.to_string() << std::endl;

    // Check if formula export is requested
    auto& config = planmt::Config::instance();
    if (config.formula_export.export_formula) {
        return export_formula_and_exit(planning_problem);
    }

    // === RELAXED PLANNING GRAPH CHECK ===
    // Create and build the RPG to check for unsolvability
    planmt::RelaxedPlanningGraph rpg(planning_problem);
    bool goals_reachable = rpg.build();

    // If goals are not reachable in the relaxed planning graph, the problem is unsolvable
    if (!goals_reachable) {
        PlanGenerationResult result;
        result.set_status(PlanGenerationResult_Status_UNSOLVABLE_PROVEN);

        auto* log_message = result.add_log_messages();
        log_message->set_level(LogMessage_LogLevel_INFO);
        log_message->set_message("Problem proven unsolvable: goals not reachable in relaxed planning graph");

        return write_result_and_exit(result, argv[2]);
    }

    // Remove unreachable actions to reduce encoding size
    size_t total_actions = planning_problem.action_count();
    size_t removed_actions = 0;
    if (planmt::Config::instance().global.enable_action_removal) {
        removed_actions = rpg.remove_unreachable_actions();
        if (planmt::Config::instance().is_info()) {
            double percentage = (double)removed_actions / total_actions * 100.0;
            std::cout << "[RPG] Removed " << removed_actions << "/" << total_actions
                        << " unreachable actions (" << std::fixed << std::setprecision(1)
                        << percentage << "%)" << std::endl;
        }
    }

    // Extract lower bound from RPG for starting timestep
    int rpg_lower_bound = rpg.get_minimum_steps_lower_bound();

    // Set the starting timestep from RPG lower bound in config
    config.planner.start_timestep = rpg_lower_bound;

    // === NUMERIC RELAXED PLANNING GRAPH DEBUG ===
    // Create Z3 context for numeric RPG testing
    z3::context ctx;

    // Create and build the numeric RPG
    if (config.is_info()) {
        std::cout << "\n=== Testing NumericRelaxedPlanningGraph ===" << std::endl;
    }

    planmt::NumericRelaxedPlanningGraph numeric_rpg(planning_problem, ctx);

    if (config.is_verbose()) {
        std::cout << "NumericRelaxedPlanningGraph created successfully" << std::endl;
        std::cout << "Building numeric RPG..." << std::endl;
    }

    auto numeric_rpg_start = std::chrono::high_resolution_clock::now();
    bool numeric_goals_reachable = numeric_rpg.build();
    auto numeric_rpg_end = std::chrono::high_resolution_clock::now();
    auto numeric_rpg_time = std::chrono::duration<double>(numeric_rpg_end - numeric_rpg_start).count();

    if (config.is_info()) {
        std::cout << "Numeric RPG build completed in " << numeric_rpg_time << "s" << std::endl;
        std::cout << "Goals reachable: " << (numeric_goals_reachable ? "YES" : "NO") << std::endl;
        std::cout << "Number of layers: " << numeric_rpg.get_layer_count() << std::endl;
    }

    // Remove unreachable actions using numeric RPG
    if (planmt::Config::instance().global.enable_action_removal) {
        auto numeric_removable = numeric_rpg.get_removable_actions();
        size_t numeric_unreachable = numeric_removable.size();
        size_t numeric_removed = numeric_rpg.remove_unreachable_actions();
        if (config.is_info()) {
            size_t total_after_boolean = planning_problem.action_count() + numeric_removed;
            double percentage = (double)numeric_removed / total_after_boolean * 100.0;
            std::cout << "[Numeric RPG] " << numeric_unreachable << " unreachable, removed " 
                        << numeric_removed << "/" << total_after_boolean
                        << " additional actions (" << std::fixed << std::setprecision(1)
                        << percentage << "%)" << std::endl;
        }
    }

    if (config.is_verbose()) {
        // Print statistics
        numeric_rpg.print_statistics();

        std::cout << "=== End NumericRelaxedPlanningGraph Test ===\n" << std::endl;
    }

    // Solve the planning problem using configuration
    PlanGenerationResult result = solve_planning_problem(planning_problem);

    // Print statistics if in debug mode, and optionally write to file
    if (config.is_debug()) {
        planmt::Stats::instance().print_all();
    }
    
    // Write statistics to file if specified
    if (!config.global.stats_file.empty()) {
        planmt::Stats::instance().write_to_file(config.global.stats_file);
    }

    return write_result_and_exit(result, argv[2]);
}